SELECT 
FROM gt_risk_assessment
WHERE org_id = #{orgId}

    AND assessment_no LIKE CONCAT('%', #{assessmentNo}, '%')


    AND risk_type_id = #{riskTypeId}


    AND business_unit = #{businessUnit}


    AND risk_level = #{riskLevel}


    AND assessment_status = #{assessmentStatus}


    AND assessment_date >= #{assessmentDateStart}


    AND assessment_date <= #{assessmentDateEnd}

ORDER BY assessment_date DESC, create_time DESC

SELECT 
FROM gt_risk_assessment
WHERE assessment_no = #{assessmentNo} AND org_id = #{orgId}

SELECT 
FROM gt_risk_assessment
WHERE risk_type_id = #{riskTypeId} 

    AND org_id = #{orgId}

ORDER BY assessment_date DESC

SELECT COALESCE(SUM(risk_exposure), 0)
FROM gt_risk_assessment
WHERE org_id = #{orgId} 
AND risk_level = #{riskLevel}
AND assessment_status = 'COMPLETED'

SELECT COALESCE(SUM(potential_loss), 0)
FROM gt_risk_assessment
WHERE org_id = #{orgId} 
AND risk_level = #{riskLevel}
AND assessment_status = 'COMPLETED'

SELECT COUNT(*)
FROM gt_risk_assessment
WHERE assessment_no = #{assessmentNo} AND org_id = #{orgId}

    AND assessment_id != #{excludeId}
